argsPayload:
{
  "command": "gh api graphql -f owner='KirkDiggler' -F number=216 -f query='query($owner:String!,$number:Int!){repository(owner:$owner,name:\"rpg-project\"){issue(number:$number){state projectItems(first:20){nodes{id project{number title url} fieldValues(first:30){nodes{... on ProjectV2ItemFieldSingleSelectValue{field{name} name optionId} ... on ProjectV2ItemFieldTextValue{field{name} text} ... on ProjectV2ItemFieldRepositoryValue{field{name} repository{nameWithOwner}} ... on ProjectV2ItemFieldLabelValue{field{name} labels(first:20){nodes{name}}}}}}}}}}'",
  "timeout": 30
}

{
  "command": "git ls-remote --heads origin main idea/216-attack-die-3d && printf '\\nRemote containing refs for head SHA:\\n' && git ls-remote origin | grep '229a16f61355b862dd3af4816bfac63f1e27c63c'",
  "timeout": 30
}

{
  "command": "gh api repos/KirkDiggler/rpg-project/pulls/217/commits --paginate --jq '.[] | [.sha, .commit.message] | @tsv' && printf '\\nChanged paths via REST:\\n' && gh api repos/KirkDiggler/rpg-project/pulls/217/files --paginate --jq '.[].filename'",
  "timeout": 30
}

{
  "command": "body=\"$(gh api repos/KirkDiggler/rpg-project/pulls/217 --jq .body)\"; printf 'Final nonempty line: <%s>\\n' \"$(printf '%s\\n' \"$body\" | sed '/^[[:space:]]*$/d' | tail -n 1)\"; printf 'Signature exact count: '; printf '%s\\n' \"$body\" | grep -Fxc '— asset-pipeline agent, on behalf of KirkDiggler'; printf 'Closes exact count: '; printf '%s\\n' \"$body\" | grep -Fxc 'Closes #216'; printf 'Body ending bytes: '; printf '%s' \"$body\" | tail -c 64 | od -An -tx1",
  "timeout": 30
}

{
  "command": "printf 'Staged paths:\\n'; git diff --cached --name-only; printf 'Worktree paths (read-only baseline):\\n'; git status --short",
  "timeout": 30
}

{
  "command": "gh api graphql -f owner='KirkDiggler' -F number=216 -f query='query($owner:String!,$number:Int!){repository(owner:$owner,name:\"rpg-project\"){issue(number:$number){state projectItems(first:20){nodes{id type project{number title url} fieldValues(first:30){nodes{__typename ... on ProjectV2ItemFieldSingleSelectValue{field{... on ProjectV2FieldCommon{name}} name optionId} ... on ProjectV2ItemFieldTextValue{field{... on ProjectV2FieldCommon{name}} text} ... on ProjectV2ItemFieldRepositoryValue{field{... on ProjectV2FieldCommon{name}} repository{nameWithOwner}} ... on ProjectV2ItemFieldLabelValue{field{... on ProjectV2FieldCommon{name}} labels(first:20){nodes{name}}}}}}}}}}' --jq '.data.repository.issue'",
  "timeout": 30
}

{
  "command": "gh api graphql -f login='KirkDiggler' -F number=19 -f query='query($login:String!,$number:Int!){user(login:$login){projectV2(number:$number){number title url closed fields(first:50){nodes{__typename ... on ProjectV2FieldCommon{id name dataType} ... on ProjectV2SingleSelectField{id name dataType options{id name}}}}}}}' --jq '.data.user.projectV2'",
  "timeout": 30
}

{
  "command": "git fetch --quiet origin main idea/216-attack-die-3d && git merge-base --is-ancestor origin/main origin/idea/216-attack-die-3d; rc=$?; printf 'origin/main ancestor of remote head: %s\\n' \"$([ \"$rc\" -eq 0 ] && echo yes || echo no)\"; printf 'remote diff paths:\\n'; git diff --name-only origin/main...origin/idea/216-attack-die-3d; printf 'remote commit chain:\\n'; git log --format='%H %s' origin/main..origin/idea/216-attack-die-3d; exit \"$rc\"",
  "timeout": 30
}

{
  "command": "for sha in 5bdec83ef2083980581ea38bd83163f9bd606148 427c3da60db15b1a84ed45d2bb353076666e0ded 229a16f61355b862dd3af4816bfac63f1e27c63c; do gh api \"repos/KirkDiggler/rpg-project/commits/$sha\" --jq '[.sha, (.parents|map(.sha)|join(\",\")), (.files|map(.filename)|join(\",\")), .commit.message] | @tsv'; done",
  "timeout": 30
}

{
  "command": "gh api 'repos/KirkDiggler/rpg-project/contents/ideas/attack-die-3d/design.md?ref=229a16f61355b862dd3af4816bfac63f1e27c63c' --jq .content | tr -d '\\n' | base64 -d | wc -l; gh api 'repos/KirkDiggler/rpg-project/contents/ideas/attack-die-3d/plan.md?ref=229a16f61355b862dd3af4816bfac63f1e27c63c' --jq .content | tr -d '\\n' | base64 -d | wc -l",
  "timeout": 30
}

{
  "command": "date -u +'%Y-%m-%dT%H:%M:%SZ'; git status --short --branch; printf 'Staged files count: '; git diff --cached --name-only | wc -l",
  "timeout": 30
}
